INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','dependent-prepositions','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"dependent-prepositions","title":"Adjectives and verbs with dependent prepositions","level":"B1","order":38,"summary":"Learn prepositions as part of a phrase, and use the right complement after them.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Learn complete combinations","Prepositions take noun-like complements","Questions can leave the preposition at the end","Keep the preposition in relative clauses"],"rules":[{"title":"Learn complete combinations","explanation":"An adjective or verb often selects a particular preposition: interested in, responsible for, depend on. These are lexical patterns rather than meanings predictable from spatial in/on/at alone. Record the phrase with a short example and its intended sense.","pattern":"**interested in** music / **depend on** support","commonMistakes":["Some words allow different prepositions with different meanings; angry with a person and angry about an event are both possible."],"examples":["“The team is interested **in** preparing the visitor guide.”","“The team is responsible **for** restoring the old portrait.”"],"skill":"form"},{"title":"Prepositions take noun-like complements","explanation":"After a preposition, use a noun, object pronoun or -ing clause when naming an action. To can itself be a preposition in expressions such as look forward to, where it is followed by -ing rather than a base verb.","pattern":"look forward to **meeting** you","commonMistakes":["Do not treat every to as an infinitive marker. Its job depends on the preceding expression."],"examples":["“The team is interested in **preparing** the visitor guide.”","“The team is responsible for **restoring** the old portrait.”"],"skill":"meaning"},{"title":"Questions can leave the preposition at the end","explanation":"A neutral direct question commonly leaves a dependent preposition near the end of its clause. Formal English can place it before whom or which, but this changes register and is not always natural with every multi-word expression.","pattern":"What are you **interested in**?","commonMistakes":["Ending an English sentence with a preposition is often entirely grammatical."],"examples":["Ask about the activity of preparing the visitor guide: “What is the team interested **in**?”","Ask about the activity of restoring the old portrait: “What is the team responsible **for**?”"],"skill":"contrast"},{"title":"Keep the preposition in relative clauses","explanation":"When a relative clause contains a dependent combination, preserve the preposition even if an object relative pronoun is omitted. A formal fronted preposition requires whom or which, not that.","pattern":"the subject **(that) she is interested in**","commonMistakes":["The subject which she is interested omits the preposition required by interested in."],"examples":["Complete the relative clause about preparing the visitor guide: “This is the activity that the team is interested **in**.”","Complete the relative clause about restoring the old portrait: “This is the activity that the team is responsible **for**.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"ee4f8fbc-4f72-5c0a-aac7-07d8a7e33a83","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is interested ____ preparing the visitor guide.”","choices":[{"id":"A","text":"at"},{"id":"B","text":"by"},{"id":"C","text":"from"},{"id":"D","text":"in"}],"answerId":"D","hint":"Recall the complete expression with **interested**, rather than a spatial rule.","explanation":"In this sense, the combination is **interested in**.","keywords":["dependent-combination"],"skill":"dependent-combination","contextKey":"dependent-prepositions-1","fingerprint":"24ff805eada69fbcb6e88acda6c68e602d814b07ee71e5071f7ede223278c46a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Recall the complete expression with **interested**, rather than a spatial rule.","In this sense, the combination is **interested in**.","Choose **in**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"“interested at” does not form the required combination for this action complement.","B":"“interested by” does not form the required combination for this action complement.","C":"“interested from” does not form the required combination for this action complement.","D":"In this sense, the combination is **interested in**."}}},{"id":"565e47da-dbd6-54a5-abe0-82f73f0ab7c2","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is interested in ____ the visitor guide.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepared"},{"id":"C","text":"preparing"},{"id":"D","text":"prepare"}],"answerId":"C","hint":"Here **in** is a preposition, so the verb after it takes **-ing**.","explanation":"After preposition **in**, use **preparing** to name the action.","keywords":["preposition-gerund"],"skill":"preposition-gerund","contextKey":"dependent-prepositions-1","fingerprint":"8a61e64cb583f3c0130c9994cf838b21f33da232436796f48b0e4fd4f989f9cb","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Here **in** is a preposition, so the verb after it takes **-ing**.","After preposition **in**, use **preparing** to name the action.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive does not fit after this dependent preposition.","B":"A past form does not name the action after the preposition.","C":"After preposition **in**, use **preparing** to name the action.","D":"The base verb cannot serve as the action complement after this preposition."}}},{"id":"482b9f45-1835-5347-a9e4-197786d57cfc","topicSlug":"dependent-prepositions","level":"B1","prompt":"Ask about the activity of preparing the visitor guide: “What is the team interested ____?”","choices":[{"id":"A","text":"from"},{"id":"B","text":"in"},{"id":"C","text":"at"},{"id":"D","text":"by"}],"answerId":"B","hint":"Question order does not remove the preposition selected by the adjective.","explanation":"The question retains **interested in**, leaving the preposition at the end.","keywords":["question-preposition"],"skill":"question-preposition","contextKey":"dependent-prepositions-1","fingerprint":"8d6693109b074f4e550aed0951e6efbdf2ba67d80278f54596a33ff3e21ed7ce","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Question order does not remove the preposition selected by the adjective.","The question retains **interested in**, leaving the preposition at the end.","Choose **in**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The question still needs the preposition in “interested in”; changing it to from breaks that combination.","B":"The question retains **interested in**, leaving the preposition at the end.","C":"The question still needs the preposition in “interested in”; changing it to at breaks that combination.","D":"The question still needs the preposition in “interested in”; changing it to by breaks that combination."}}},{"id":"270b1a76-4411-525f-a627-d0dbe2d0ce1c","topicSlug":"dependent-prepositions","level":"B1","prompt":"Complete the relative clause about preparing the visitor guide: “This is the activity that the team is interested ____.”","choices":[{"id":"A","text":"at"},{"id":"B","text":"by"},{"id":"C","text":"in"},{"id":"D","text":"—"}],"answerId":"C","hint":"The relative clause must preserve the **whole adjective + preposition** pattern.","explanation":"The relative clause still needs **interested in**; that represents the activity governed by the preposition.","keywords":["relative-preposition"],"skill":"relative-preposition","contextKey":"dependent-prepositions-1","fingerprint":"506e0c73ca805cbb5d8508706af76b900aef70e9c99f4849a142a7f089499cf6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The relative clause must preserve the **whole adjective + preposition** pattern.","The relative clause still needs **interested in**; that represents the activity governed by the preposition.","Choose **in**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The adjective takes in in this sense, not at.","B":"The adjective takes in in this sense, not by.","C":"The relative clause still needs **interested in**; that represents the activity governed by the preposition.","D":"Omitting the relative object does not license omitting its required preposition."}}},{"id":"f3deda98-c88c-5600-a1e6-0f593c8bb988","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is responsible ____ restoring the old portrait.”","choices":[{"id":"A","text":"by"},{"id":"B","text":"from"},{"id":"C","text":"for"},{"id":"D","text":"at"}],"answerId":"C","hint":"Recall the complete expression with **responsible**, rather than a spatial rule.","explanation":"In this sense, the combination is **responsible for**.","keywords":["dependent-combination"],"skill":"dependent-combination","contextKey":"dependent-prepositions-2","fingerprint":"bcbb0d11cfe9cc4b1e6785aadf75c5bb4cfa049de5802c8e5e6381300be33eff","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Recall the complete expression with **responsible**, rather than a spatial rule.","In this sense, the combination is **responsible for**.","Choose **for**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"“responsible by” does not form the required combination for this action complement.","B":"“responsible from” does not form the required combination for this action complement.","C":"In this sense, the combination is **responsible for**.","D":"“responsible at” does not form the required combination for this action complement."}}},{"id":"9b8b7f57-72f4-5142-a45d-77916f910229","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is responsible for ____ the old portrait.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restored"},{"id":"C","text":"restoring"},{"id":"D","text":"restore"}],"answerId":"C","hint":"Here **for** is a preposition, so the verb after it takes **-ing**.","explanation":"After preposition **for**, use **restoring** to name the action.","keywords":["preposition-gerund"],"skill":"preposition-gerund","contextKey":"dependent-prepositions-2","fingerprint":"4ae33924082ff0e7de575bbe5cd918964c227c70b7e8748da7cf6ecb27a1f94f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Here **for** is a preposition, so the verb after it takes **-ing**.","After preposition **for**, use **restoring** to name the action.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive does not fit after this dependent preposition.","B":"A past form does not name the action after the preposition.","C":"After preposition **for**, use **restoring** to name the action.","D":"The base verb cannot serve as the action complement after this preposition."}}},{"id":"a1683376-8db5-57d4-a03f-394fe87b804a","topicSlug":"dependent-prepositions","level":"B1","prompt":"Ask about the activity of restoring the old portrait: “What is the team responsible ____?”","choices":[{"id":"A","text":"from"},{"id":"B","text":"for"},{"id":"C","text":"at"},{"id":"D","text":"by"}],"answerId":"B","hint":"Question order does not remove the preposition selected by the adjective.","explanation":"The question retains **responsible for**, leaving the preposition at the end.","keywords":["question-preposition"],"skill":"question-preposition","contextKey":"dependent-prepositions-2","fingerprint":"4f858e81b5465751cff862d212d734935aa6ef22ce6c5ca2ecfc5f0ed3c3af5c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Question order does not remove the preposition selected by the adjective.","The question retains **responsible for**, leaving the preposition at the end.","Choose **for**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The question still needs the preposition in “responsible for”; changing it to from breaks that combination.","B":"The question retains **responsible for**, leaving the preposition at the end.","C":"The question still needs the preposition in “responsible for”; changing it to at breaks that combination.","D":"The question still needs the preposition in “responsible for”; changing it to by breaks that combination."}}},{"id":"68a5fefb-3402-5613-a25d-2a244e1cee8c","topicSlug":"dependent-prepositions","level":"B1","prompt":"Complete the relative clause about restoring the old portrait: “This is the activity that the team is responsible ____.”","choices":[{"id":"A","text":"by"},{"id":"B","text":"for"},{"id":"C","text":"—"},{"id":"D","text":"at"}],"answerId":"B","hint":"The relative clause must preserve the **whole adjective + preposition** pattern.","explanation":"The relative clause still needs **responsible for**; that represents the activity governed by the preposition.","keywords":["relative-preposition"],"skill":"relative-preposition","contextKey":"dependent-prepositions-2","fingerprint":"a9c27e6dbfcc016580380a8c1256486ff3c25bb0437f195dc690ebb85a32c76c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The relative clause must preserve the **whole adjective + preposition** pattern.","The relative clause still needs **responsible for**; that represents the activity governed by the preposition.","Choose **for**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The adjective takes for in this sense, not by.","B":"The relative clause still needs **responsible for**; that represents the activity governed by the preposition.","C":"Omitting the relative object does not license omitting its required preposition.","D":"The adjective takes for in this sense, not at."}}},{"id":"aa491e86-c23f-51cc-ad43-5bf649932a47","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is capable ____ measuring the garden fence.”","choices":[{"id":"A","text":"of"},{"id":"B","text":"at"},{"id":"C","text":"by"},{"id":"D","text":"from"}],"answerId":"A","hint":"Recall the complete expression with **capable**, rather than a spatial rule.","explanation":"In this sense, the combination is **capable of**.","keywords":["dependent-combination"],"skill":"dependent-combination","contextKey":"dependent-prepositions-3","fingerprint":"fbfcd49c6fde397d53f55378fc1e274c07d0236d87599919ad3662d010bcb520","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Recall the complete expression with **capable**, rather than a spatial rule.","In this sense, the combination is **capable of**.","Choose **of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In this sense, the combination is **capable of**.","B":"“capable at” does not form the required combination for this action complement.","C":"“capable by” does not form the required combination for this action complement.","D":"“capable from” does not form the required combination for this action complement."}}},{"id":"a3c65467-806f-5c20-a5aa-9390cda3ae08","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is capable of ____ the garden fence.”","choices":[{"id":"A","text":"measuring"},{"id":"B","text":"measure"},{"id":"C","text":"to measure"},{"id":"D","text":"measured"}],"answerId":"A","hint":"Here **of** is a preposition, so the verb after it takes **-ing**.","explanation":"After preposition **of**, use **measuring** to name the action.","keywords":["preposition-gerund"],"skill":"preposition-gerund","contextKey":"dependent-prepositions-3","fingerprint":"0aa21c8709ec7347e1018bd02478fecf5a5f527c554c43c655ff9e3b79aefd20","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Here **of** is a preposition, so the verb after it takes **-ing**.","After preposition **of**, use **measuring** to name the action.","Choose **measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After preposition **of**, use **measuring** to name the action.","B":"The base verb cannot serve as the action complement after this preposition.","C":"A to-infinitive does not fit after this dependent preposition.","D":"A past form does not name the action after the preposition."}}},{"id":"b643b5df-0e89-5fe5-a1a4-4292b301142f","topicSlug":"dependent-prepositions","level":"B1","prompt":"Ask about the activity of measuring the garden fence: “What is the team capable ____?”","choices":[{"id":"A","text":"from"},{"id":"B","text":"of"},{"id":"C","text":"at"},{"id":"D","text":"by"}],"answerId":"B","hint":"Question order does not remove the preposition selected by the adjective.","explanation":"The question retains **capable of**, leaving the preposition at the end.","keywords":["question-preposition"],"skill":"question-preposition","contextKey":"dependent-prepositions-3","fingerprint":"41d616efe9b82ae7983916a467a6069e0e3dc93b02147d85107931f4916f724f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Question order does not remove the preposition selected by the adjective.","The question retains **capable of**, leaving the preposition at the end.","Choose **of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The question still needs the preposition in “capable of”; changing it to from breaks that combination.","B":"The question retains **capable of**, leaving the preposition at the end.","C":"The question still needs the preposition in “capable of”; changing it to at breaks that combination.","D":"The question still needs the preposition in “capable of”; changing it to by breaks that combination."}}},{"id":"a6f1706f-f230-5363-ad60-0c8b0c5c92d1","topicSlug":"dependent-prepositions","level":"B1","prompt":"Complete the relative clause about measuring the garden fence: “This is the activity that the team is capable ____.”","choices":[{"id":"A","text":"at"},{"id":"B","text":"by"},{"id":"C","text":"of"},{"id":"D","text":"—"}],"answerId":"C","hint":"The relative clause must preserve the **whole adjective + preposition** pattern.","explanation":"The relative clause still needs **capable of**; that represents the activity governed by the preposition.","keywords":["relative-preposition"],"skill":"relative-preposition","contextKey":"dependent-prepositions-3","fingerprint":"6815c9d0bd466d1ea79429d9ea02bbbd72102e5d1b4151f39fb84614d14cd709","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The relative clause must preserve the **whole adjective + preposition** pattern.","The relative clause still needs **capable of**; that represents the activity governed by the preposition.","Choose **of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The adjective takes of in this sense, not at.","B":"The adjective takes of in this sense, not by.","C":"The relative clause still needs **capable of**; that represents the activity governed by the preposition.","D":"Omitting the relative object does not license omitting its required preposition."}}},{"id":"531b726c-b22a-5a5d-ac4f-4955d0506844","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is committed ____ translating the travel leaflet.”","choices":[{"id":"A","text":"by"},{"id":"B","text":"from"},{"id":"C","text":"to"},{"id":"D","text":"at"}],"answerId":"C","hint":"Recall the complete expression with **committed**, rather than a spatial rule.","explanation":"In this sense, the combination is **committed to**.","keywords":["dependent-combination"],"skill":"dependent-combination","contextKey":"dependent-prepositions-4","fingerprint":"d2f071e994eb3fb8399c309acf02d994a5946ceebc4a10debeaa386f3fcbc0c7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Recall the complete expression with **committed**, rather than a spatial rule.","In this sense, the combination is **committed to**.","Choose **to**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"“committed by” does not form the required combination for this action complement.","B":"“committed from” does not form the required combination for this action complement.","C":"In this sense, the combination is **committed to**.","D":"“committed at” does not form the required combination for this action complement."}}},{"id":"e44fb15f-59ee-5849-afbe-8a1ddb5e1363","topicSlug":"dependent-prepositions","level":"B1","prompt":"“The team is committed to ____ the travel leaflet.”","choices":[{"id":"A","text":"translating"},{"id":"B","text":"translate"},{"id":"C","text":"to translate"},{"id":"D","text":"translated"}],"answerId":"A","hint":"Here **to** is a preposition, so the verb after it takes **-ing**.","explanation":"After preposition **to**, use **translating** to name the action.","keywords":["preposition-gerund"],"skill":"preposition-gerund","contextKey":"dependent-prepositions-4","fingerprint":"11ae4589f49b35061977472ca83d71490db8996aec066879e52525dedced178d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-dependent-prepositions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"